[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory,
 [string]$ProviderPath="$PSScriptRoot\..\..\controller\providers\Microsoft365SigninTask.ps1"
)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$Experiment='EXP-113';$TaskName='Lacksan-EXP-113-LabHarness';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Elevation { $p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(!$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required.'} }
function Ensure([string]$p){if(!(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
function WJ([string]$p,$v){$v|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $p -Encoding UTF8}
function RJ([string]$p){if(!(Test-Path -LiteralPath $p)){throw "Required state missing: $p"};Get-Content -LiteralPath $p -Raw|ConvertFrom-Json}
function BootUtc {((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()}
function Med($v){$a=@($v|Where-Object{$null-ne$_}|%{[double]$_}|Sort-Object);if(!$a.Count){return $null};$m=[int][math]::Floor($a.Count/2);if($a.Count%2){return $a[$m]};($a[$m-1]+$a[$m])/2}
function Mad($v){$a=@($v|Where-Object{$null-ne$_}|%{[double]$_});if(!$a.Count){return $null};$m=Med $a;Med @($a|%{[math]::Abs($_-$m)})}
function Paths($d){[pscustomobject]@{Harness=Join-Path $d 'harness-state.json';Provider=Join-Path $d 'provider-state.json';ProviderLog=Join-Path $d 'provider-events.jsonl';Summary=Join-Path $d 'summary.json'}}
function Dir {if($RunDirectory){return (Resolve-Path $RunDirectory).Path};$a=RJ $ActivePointer;(Resolve-Path ([string]$a.runDirectory)).Path}
function Log($d,$e,$r,$data){[ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$Experiment;component='lab-harness';action=$Action;event=$e;result=$r;machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;data=$data}|ConvertTo-Json -Compress -Depth 12|Add-Content (Join-Path $d 'lab-events.jsonl') -Encoding UTF8}
function Provider($a,$d,[switch]$WhatIfOnly){$p=Paths $d;$x=@{Action=$a;StatePath=$p.Provider;LogPath=$p.ProviderLog};if($WhatIfOnly){& $ProviderPath @x -WhatIf}else{& $ProviderPath @x}}
function ResumeTask {Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue}
function RegisterResume($d){if(ResumeTask){throw 'Continuation task collision.'};$exe=(Get-Command powershell.exe -ErrorAction Stop).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ProviderPath `"$ProviderPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$pr=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;$s=New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 20);if($PSCmdlet.ShouldProcess($TaskName,'Register reversible continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Settings $s|Out-Null}}
function RemoveResume($d){if(ResumeTask){if($PSCmdlet.ShouldProcess($TaskName,'Remove continuation task')){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false;Log $d 'continuation-task-removed' 'pass' @{task=$TaskName}}}}
function Protected { $svc=@();foreach($n in 'WinDefend','mpssvc','wuauserv','UsoSvc','BITS','Tailscale','TermService'){try{$s=Get-Service $n -ErrorAction Stop;$svc+=[pscustomobject]@{name=$n;status="$($s.Status)";startType="$($s.StartType)"}}catch{$svc+=[pscustomobject]@{name=$n;status='absent';startType=$null}}};[pscustomobject]@{services=$svc;processes=@(Get-Process -ErrorAction SilentlyContinue|?{$_.ProcessName-match'(?i)omnissa|horizon|msrdc|mstsc|tailscale|windowsapp'}|select ProcessName,Id,Responding)} }
function TaskState($ps){$t=Get-ScheduledTask -TaskName ([string]$ps.task.TaskName) -TaskPath ([string]$ps.task.TaskPath) -ErrorAction SilentlyContinue;if(!$t){return [pscustomobject]@{present=$false;enabled=$null}};[pscustomobject]@{present=$true;enabled=[bool]$t.Settings.Enabled}}
function AssertBase($ps){$s=TaskState $ps;if(!$s.present -or !$s.enabled){throw 'Baseline Microsoft 365 sign-in task drift.'}}
function AssertTreat($ps){$s=TaskState $ps;if(!$s.present -or $s.enabled){throw 'Treatment Microsoft 365 sign-in task drift.'}}
function Sample($phase,$ordinal,$d,$ps){$boot=BootUtc;$pb=Protected;$before=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$sys=@();$count=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds);for($i=0;$i-lt$count;$i++){$c=Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'";$k=Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'";$sys+=[pscustomobject]@{cpu=[double]$c.PercentProcessorTime;disk=[double]$k.DiskBytesPersec};if($i-lt$count-1){Start-Sleep $SampleIntervalSeconds}};$after=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$e=Get-Process explorer -ErrorAction SilentlyContinue|Sort-Object StartTime|Select-Object -First 1;[ordered]@{schemaVersion=1;experiment=$Experiment;phase=$phase;ordinal=$ordinal;bootUtc=$boot.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');task=TaskState $ps;taskIdentity=@{taskPath=[string]$ps.task.TaskPath;taskName=[string]$ps.task.TaskName;xmlSha256=[string]$ps.task.XmlSha256};desktopProxy=@{explorerPresent=[bool]$e;bootToExplorerStartMs=if($e){($e.StartTime.ToUniversalTime()-$boot).TotalMilliseconds}else{$null}};system=@{cpuMedianPercent=Med @($sys|% cpu);cpuMadPercent=Mad @($sys|% cpu);diskMedianBytesPerSec=Med @($sys|% disk);diskMadBytesPerSec=Mad @($sys|% disk)};protected=@{before=$pb;after=Protected};functionalEvidence=@{manualOfficeLaunch='needs-evidence';clickToRunServicing='needs-evidence';activationDocumentsAddins='needs-evidence';protectedApplicationReadiness='needs-evidence'};instrumentation=@{collectorCpuDeltaMs=$after-$before;sampleCount=$sys.Count;sampleIntervalSeconds=$SampleIntervalSeconds}}}
function Summary($d){$r=@(Get-ChildItem $d -Filter 'run-*.json' -File|Sort Name|%{RJ $_.FullName});$g=[ordered]@{};foreach($ph in 'Baseline','Treatment'){$x=@($r|? phase -eq $ph);$g[$ph]=@{runs=$x.Count;bootToExplorerStartMs=@{median=Med @($x|%{$_.desktopProxy.bootToExplorerStartMs});mad=Mad @($x|%{$_.desktopProxy.bootToExplorerStartMs})};cpuMedianPercent=@{median=Med @($x|%{$_.system.cpuMedianPercent});mad=Mad @($x|%{$_.system.cpuMedianPercent})};diskMedianBytesPerSec=@{median=Med @($x|%{$_.system.diskMedianBytesPerSec});mad=Mad @($x|%{$_.system.diskMedianBytesPerSec})}}};$rb=@($r|? phase -eq 'RollbackVerify'|select -Last 1);$o=[ordered]@{schemaVersion=1;experiment=$Experiment;generatedUtc=(Get-Date).ToUniversalTime().ToString('o');groups=$g;rollbackRebootVerified=($rb.Count-eq1-and[bool]$rb[0].task.present-and[bool]$rb[0].task.enabled);remainingEvidence=@('Manual Office application launch','Click-to-Run servicing and update readiness','Activation documents and add-ins','Timed Omnissa Windows App Remote Desktop and Tailscale readiness','Instrumentation qualification')};WJ (Join-Path $d 'summary.json') $o;$o}
function Reboot($d){if($AllowAutomaticReboot){Log $d 'reboot-requested' 'pass' @{};Restart-Computer -Force}else{Log $d 'reboot-required' 'needs-evidence' @{};Write-Output 'Reboot required; continuation resumes at next interactive logon.'}}
Elevation;if(!(Test-Path $ProviderPath)){throw 'EXP-113 provider missing.'}
try{switch($Action){
 'Start'{Ensure $EvidenceRoot;if(Test-Path $ActivePointer){throw 'Active EXP-113 run exists.'};$check=Provider Check $EvidenceRoot;Provider DryRun $EvidenceRoot|Out-Null;if($WhatIfPreference){$null=$PSCmdlet.ShouldProcess($TaskName,"Prepare $RunsPerArm matched boots");return $check};$d=Join-Path $EvidenceRoot ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));Ensure $d;$p=Paths $d;Provider Capture $d|Out-Null;WJ $p.Harness @{schemaVersion=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null};WJ $ActivePointer @{runDirectory=$d};RegisterResume $d;Log $d 'started' 'pass' @{runsPerArm=$RunsPerArm;sampleSeconds=$SampleSeconds};Reboot $d}
 'Continue'{$d=Dir;$p=Paths $d;$s=RJ $p.Harness;$ps=RJ $p.Provider;$boot=(BootUtc).ToString('o');if($s.lastBootUtc-eq$boot){throw 'Duplicate same-boot collection refused.'};if($s.phase-eq'RollbackVerify'){AssertBase $ps;$t=Sample RollbackVerify 1 $d $ps;WJ (Join-Path $d 'run-RollbackVerify-01.json') $t;Summary $d|Out-Null;RemoveResume $d;Remove-Item $ActivePointer -Force;Log $d 'completed' 'pass' @{rollbackRebootVerified=$true};return RJ $p.Summary};if($s.phase-eq'Baseline'){AssertBase $ps}else{AssertTreat $ps;Provider Verify $d|Out-Null;Provider VerifyReboot $d|Out-Null};$ord=[int]$s.completedRuns+1;$t=Sample $s.phase $ord $d $ps;WJ (Join-Path $d ("run-{0}-{1:d2}.json" -f $s.phase,$ord)) $t;$s.completedRuns=$ord;$s.lastBootUtc=$boot;if($ord-ge[int]$s.runsPerArm){if($s.phase-eq'Baseline'){Provider Apply $d|Out-Null;Provider Verify $d|Out-Null;$s.phase='Treatment';$s.completedRuns=0}elseif($s.phase-eq'Treatment'){Provider Rollback $d|Out-Null;$s.phase='RollbackVerify';$s.completedRuns=0}};WJ $p.Harness $s;Reboot $d}
 'Status'{$d=Dir;$p=Paths $d;[pscustomobject]@{RunDirectory=$d;Harness=RJ $p.Harness;Provider=RJ $p.Provider;ContinuationTaskPresent=[bool](ResumeTask)}}
 'Summarize'{$d=Dir;Summary $d}
 'Stop'{$d=Dir;$p=Paths $d;if(Test-Path $p.Provider){$ps=RJ $p.Provider;$ts=TaskState $ps;if($ts.present-and!$ts.enabled){Provider Rollback $d|Out-Null}};RemoveResume $d;if(Test-Path $ActivePointer){Remove-Item $ActivePointer -Force};Log $d 'stopped' 'pass' @{rollbackAttempted=$true}}
}}catch{try{if($RunDirectory -or (Test-Path $ActivePointer)){$d=Dir;Log $d 'failure' 'failure' @{message=$_.Exception.Message;type=$_.Exception.GetType().FullName}}}catch{};throw}
